def drive(me, enemy, arena):
    dx = enemy.x - me.x
    dy = enemy.y - me.y
    dist = hypot(dx, dy)
    eh = radians(enemy.heading)
    fx = cos(eh)
    fy = sin(eh)
    px = -fy
    py = fx
    ox = 1.5
    oy = -0.8
    c1x = enemy.x + ox*px + oy*fx
    c1y = enemy.y + ox*py + oy*fy
    c2x = enemy.x - ox*px + oy*fx
    c2y = enemy.y - ox*py + oy*fy
    d1 = hypot(c1x - me.x, c1y - me.y)
    d2 = hypot(c2x - me.x, c2y - me.y)
    if d1 < d2:
        tx, ty = c1x, c1y
    else:
        tx, ty = c2x, c2y
    if dist < 1.5:
        tx, ty = enemy.x, enemy.y
    tr = hypot(tx, ty)
    if tr > 5.5:
        tx *= 5.5 / tr
        ty *= 5.5 / tr
    r = hypot(me.x, me.y)
    if r > 5.0:
        outward = me.x*me.vx + me.y*me.vy
        if outward > 0 or r > 5.5:
            tx = 0
            ty = 0
    b = bearing_to(tx, ty)
    if abs(b) > 120:
        if b > 0:
            return (-1, 1)
        else:
            return (1, -1)
    elif abs(b) > 45:
        if b > 0:
            return (0.1, 1)
        else:
            return (1, 0.1)
    elif abs(b) > 5:
        if b > 0:
            return (0.7, 1)
        else:
            return (1, 0.7)
    else:
        return (1, 1)

